package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.InformationRuntime;import net.minecraft.core.BlockPos;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Two-wire conceptual differential medium. Payload remains digital; quality models common-mode rejection. */
public class DifferentialDataPairBlock extends Block{public DifferentialDataPairBlock(Properties p){super(p);}@Override public MapCodec<DifferentialDataPairBlock> codec(){return RedstoneEngineering.DIFFERENTIAL_DATA_PAIR_CODEC.value();}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Differential pair: bit="+(InformationRuntime.value(l,"diff",p)&1)+" quality="+InformationRuntime.quality(l,"diff",p)+"%"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
